pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 d, uint256 w, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(d <= 1e24);
        vm.assume(w <= d);
        vm.deal(actor, d + 1);
        vm.prank(actor);
        c.deposit{value: d}();
        vm.prank(actor);
        c.withdraw(w);
        // withdraw the entire recorded balance
        vm.prank(actor);
        c.withdraw(d - w);
        // the account is now empty: any further withdrawal must revert
        bool ok;
        vm.prank(actor);
        try c.withdraw(1) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

