pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        // fund the actor and deposit exactly `amount`, so withdrawing `amount`
        // is always admissible for the reference contract
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a withdrawal of a previously deposited amount always succeeds.
        // The mutant computes `balances[msg.sender] -= amount - 1`, which underflows
        // (and thus reverts) when amount == 0, breaking the rule for that input.
        assertTrue(ok);
    }
}

