pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 depositAmt, uint256 withdrawAmt, uint256 extra) public {
        address actor = address(0xBEEF);
        depositAmt = bound(depositAmt, 1, 100 ether);
        withdrawAmt = bound(withdrawAmt, 0, depositAmt);
        extra = bound(extra, 1, 100 ether);

        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.deposit{value: depositAmt}();

        vm.prank(actor);
        c.withdraw(withdrawAmt);

        // remaining recorded balance is depositAmt - withdrawAmt;
        // withdrawing more than that must revert.
        uint256 over = (depositAmt - withdrawAmt) + extra;
        bool ok;
        vm.prank(actor);
        try c.withdraw(over) { ok = true; } catch { ok = false; }

        assertTrue(!ok);
    }
}

