pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint96 depositAmt, uint96 withdrawAmt) public {
        vm.assume(actor != address(0) && actor != address(c));
        depositAmt = uint96(bound(uint256(depositAmt), 1, type(uint96).max));
        withdrawAmt = uint96(bound(uint256(withdrawAmt), 1, uint256(depositAmt)));

        vm.deal(actor, uint256(depositAmt));
        vm.prank(actor);
        c.deposit{value: uint256(depositAmt)}();

        vm.prank(actor);
        c.withdraw(uint256(withdrawAmt));

        // Rule: after a legitimate withdrawal, refund() must always succeed,
        // since it only sends the remaining recorded balance, which is fully backed.
        vm.prank(actor);
        bool ok;
        try c.refund() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

