pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0));
        // fund c via a deposit from a fuzzed actor
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();
        // destination that cannot receive Ether: the precompute address of the helper we deploy after the call
        address to = address(uint160(uint256(keccak256("dest"))));
        vm.assume(to.code.length == 0 && to != address(c) && to != address(this) && to.balance == 0);
        // creator drives migrateTo toward the refusing destination
        vm.prank(address(this));
        bool ok;
        try c.migrateTo(to) { ok = true; } catch { ok = false; }
        // General rule: migrating to a non-payable destination must revert; c's funds must not leave via such a call.
        assertTrue(!ok && address(c).balance == amount);
    }
}

